/**
 * 数据库层 —— 基于 sql.js（SQLite WASM 版，纯 JS 无需原生编译）
 * 提供与 better-sqlite3 类似的同步 API：prepare/run/get/all、exec、transaction
 * 数据在每次写操作后持久化到 mro.db 文件
 */
const initSqlJs = require('sql.js');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const DB_PATH = path.join(__dirname, 'mro.db');
const WASM_DIR = path.join(__dirname, 'node_modules', 'sql.js', 'dist');

let real = null; // 初始化完成后的 Database 实例

function hash(buf) {
  return crypto.createHash('sha1').update(buf).digest('hex');
}

class Statement {
  constructor(db, sql) {
    this.db = db;
    this.sql = sql;
  }

  _bind(stmt, params) {
    // sql.js 不接受 undefined，统一转 null
    stmt.bind(params.map((p) => (p === undefined ? null : p)));
  }

  run(...params) {
    const stmt = this.db._db.prepare(this.sql);
    try {
      this._bind(stmt, params);
      stmt.step();
      const rowid = this.db._db.exec('SELECT last_insert_rowid() AS id')[0].values[0][0];
      this.db._persist();
      return { changes: this.db._db.getRowsModified(), lastInsertRowid: rowid };
    } finally {
      stmt.free();
    }
  }

  get(...params) {
    const stmt = this.db._db.prepare(this.sql);
    try {
      this._bind(stmt, params);
      return stmt.step() ? stmt.getAsObject() : undefined;
    } finally {
      stmt.free();
    }
  }

  all(...params) {
    const stmt = this.db._db.prepare(this.sql);
    try {
      this._bind(stmt, params);
      const rows = [];
      while (stmt.step()) rows.push(stmt.getAsObject());
      return rows;
    } finally {
      stmt.free();
    }
  }
}

class Database {
  constructor(SQL, sqlDb) {
    this._SQL = SQL;
    this._db = sqlDb;
    this._txnDepth = 0;
    this._lastHash = null;
  }

  /** 数据文件被外部修改（如运行期间执行 npm run seed）时，重新加载内存库 */
  reloadIfChanged() {
    if (this._txnDepth > 0) return; // 事务进行中不重载，下次事件再处理
    let data;
    try {
      data = fs.readFileSync(DB_PATH);
    } catch {
      return;
    }
    if (hash(data) === this._lastHash) return; // 是自身落盘或无变化
    try {
      const fresh = new this._SQL.Database(data);
      fresh.exec('PRAGMA foreign_keys = ON');
      this._db.close();
      this._db = fresh;
      this._lastHash = hash(data);
      console.log('🔄 检测到数据文件外部变更，已重新加载数据库');
    } catch {
      // 文件可能正在写入中，忽略本次，等待下一次变更事件
    }
  }

  exec(sql) {
    this._db.exec(sql);
    this._persist();
  }

  prepare(sql) {
    return new Statement(this, sql);
  }

  pragma() { /* sql.js 内存模式无需 journal/WAL 设置 */ }

  transaction(fn) {
    return (...args) => {
      const outermost = this._txnDepth === 0;
      if (outermost) this._db.exec('BEGIN');
      this._txnDepth++;
      try {
        const result = fn(...args);
        this._txnDepth--;
        if (outermost) {
          this._db.exec('COMMIT');
          this._persist();
        }
        return result;
      } catch (err) {
        this._txnDepth--;
        if (outermost) this._db.exec('ROLLBACK');
        throw err;
      }
    };
  }

  _persist() {
    if (this._txnDepth > 0) return; // 事务提交时统一落盘
    const data = Buffer.from(this._db.export());
    const tmp = DB_PATH + '.tmp';
    fs.writeFileSync(tmp, data);
    fs.renameSync(tmp, DB_PATH); // 原子替换，避免并发读到半截文件
    this._lastHash = hash(data);
  }
}

