1	const express = require('express');
2	const { db, addLog } = require('../db');
3	
4	const router = express.Router();
5	
6	const CARD_DETAIL_SQL = `
7	  SELECT w.*, a.registration, a.model, a.base,
8	         t.name AS assignee_name, t.employee_no AS assignee_no, t.role AS assignee_role
9	  FROM work_cards w
10	  JOIN aircraft a ON a.id = w.aircraft_id
11	  LEFT JOIN technicians t ON t.id = w.assigned_to
12	`;
13	
14	function getCardFull(id) {
15	  const card = db.prepare(CARD_DETAIL_SQL + ' WHERE w.id = ?').get(id);
16	  if (!card) return null;
17	  card.steps = db.prepare(`
18	    SELECT s.*, t.name AS signer_name, t.employee_no AS signer_no
19	    FROM work_card_steps s LEFT JOIN technicians t ON t.id = s.signed_by
20	    WHERE s.work_card_id = ? ORDER BY s.seq
21	  `).all(id);
22	  card.parts = db.prepare('SELECT * FROM parts_requests WHERE work_card_id = ? ORDER BY id').all(id);
23	  card.release = db.prepare(`
24	    SELECT r.*, t.name AS releaser_name, t.license_no
25	    FROM release_records r JOIN technicians t ON t.id = r.released_by
26	    WHERE r.work_card_id = ?
27	  `).get(id);
28	  card.logs = db.prepare('SELECT * FROM work_logs WHERE work_card_id = ? ORDER BY created_at DESC, id DESC').all(id);
29	  return card;
30	}
31	
32	// 工卡列表，支持 ?status= &aircraft_id= &priority= 过滤；默认不含已作废
33	router.get('/', (req, res) => {
34	  const { status, aircraft_id, priority } = req.query;
35	  let sql = CARD_DETAIL_SQL + ' WHERE 1=1';
36	  const params = [];
37	  if (status) { sql += ' AND w.status = ?'; params.push(status); }
38	  else { sql += " AND w.status != '已作废'"; } // 作废工卡退出在办清单，需显式查询
39	  if (aircraft_id) { sql += ' AND w.aircraft_id = ?'; params.push(aircraft_id); }
40	  if (priority) { sql += ' AND w.priority = ?'; params.push(priority); }
41	  sql += ' ORDER BY CASE w.priority WHEN \'AOG\' THEN 0 WHEN \'加急\' THEN 1 ELSE 2 END, w.due_date';
42	  res.json(db.prepare(sql).all(...params));
43	});
44	
45	// 工卡详情
46	router.get('/:id', (req, res) => {
47	  const card = getCardFull(req.params.id);
48	  if (!card) return res.status(404).json({ error: '工卡不存在' });
49	  res.json(card);
50	});
51	
52	// 创建工卡（含步骤）
53	router.post('/', (req, res) => {
54	  const { aircraft_id, title, type, priority, description, due_date, steps, created_by } = req.body;
55	  if (!aircraft_id || !title || !Array.isArray(steps) || steps.length === 0) {
56	    return res.status(400).json({ error: '飞机、标题、至少一个步骤为必填项' });
57	  }
58	  const ac = db.prepare('SELECT * FROM aircraft WHERE id = ?').get(aircraft_id);
59	  if (!ac) return res.status(404).json({ error: '飞机不存在' });
60	
61	  const tx = db.transaction(() => {
62	    const seq = db.prepare("SELECT COUNT(*) c FROM work_cards WHERE card_no LIKE 'WC-2026-%'").get().c + 1;
63	    const cardNo = `WC-2026-${String(900 + seq).padStart(4, '0')}`;
64	    const info = db.prepare(`
65	      INSERT INTO work_cards (card_no, aircraft_id, title, type, priority, status, description, created_by, due_date)
66	      VALUES (?, ?, ?, ?, ?, '待派工', ?, ?, ?)
67	    `).run(cardNo, aircraft_id, title, type || '航线维修', priority || '正常',
68	      description || '', created_by || '生产控制', due_date || null);
69	    const cardId = info.lastInsertRowid;
70	    const insStep = db.prepare('INSERT INTO work_card_steps (work_card_id, seq, content, standard) VALUES (?, ?, ?, ?)');
71	    steps.forEach((s, i) => insStep.run(cardId, i + 1, s.content, s.standard || ''));
72	    addLog(cardId, created_by || '生产控制', '创建工卡', `${type || '航线维修'} / ${priority || '正常'}`);
73	    if (priority === 'AOG') {
74	      db.prepare("UPDATE aircraft SET status = '停场维修' WHERE id = ?").run(aircraft_id);
75	      addLog(cardId, '系统', '状态联动', `AOG 工卡，${ac.registration} 转为停场维修`);
76	    }
77	    return cardId;
78	  });
79	  const cardId = tx();
80	  res.status(201).json(getCardFull(cardId));
81	});
82	
83	// 派工
84	router.post('/:id/assign', (req, res) => {
85	  const { technician_id, operator } = req.body;
86	  const card = db.prepare('SELECT * FROM work_cards WHERE id = ?').get(req.params.id);
87	  if (!card) return res.status(404).json({ error: '工卡不存在' });
88	  if (card.status !== '待派工') return res.status(409).json({ error: `当前状态为「${card.status}」，不能派工` });
89	  const tech = db.prepare('SELECT * FROM technicians WHERE id = ?').get(technician_id);
90	  if (!tech) return res.status(404).json({ error: '维修人员不存在' });
91	
92	  db.prepare("UPDATE work_cards SET assigned_to = ?, status = '进行中' WHERE id = ?").run(technician_id, card.id);
93	  addLog(card.id, operator || '生产控制', '派工', `派工给 ${tech.name}(${tech.employee_no})`);
94	  res.json(getCardFull(card.id));
95	});
96	
97	// 步骤签署
98	router.post('/:id/steps/:stepId/sign', (req, res) => {
99	  const { technician_id } = req.body;
100	  const card = db.prepare('SELECT * FROM work_cards WHERE id = ?').get(req.params.id);
101	  if (!card) return res.status(404).json({ error: '工卡不存在' });
102	  if (card.status === '缺件挂起') return res.status(409).json({ error: '工卡处于缺件挂起状态，航材到货后才能继续施工' });
103	  if (card.status !== '进行中') return res.status(409).json({ error: `当前状态为「${card.status}」，不能签署步骤` });
104	  if (card.assigned_to !== Number(technician_id)) {
105	    return res.status(403).json({ error: '只有被派工人才能签署本工卡步骤' });
106	  }
107	  const step = db.prepare('SELECT * FROM work_card_steps WHERE id = ? AND work_card_id = ?').get(req.params.stepId, card.id);
108	  if (!step) return res.status(404).json({ error: '步骤不存在' });
109	  if (step.status === '已签署') return res.status(409).json({ error: '该步骤已签署' });
110	  const prevUnsigned = db.prepare(
111	    "SELECT COUNT(*) c FROM work_card_steps WHERE work_card_id = ? AND seq < ? AND status = '待执行'"
112	  ).get(card.id, step.seq).c;
113	  if (prevUnsigned > 0) return res.status(409).json({ error: '请按顺序签署，前序步骤尚未完成' });
114	
115	  const tx = db.transaction(() => {
116	    db.prepare("UPDATE work_card_steps SET status = '已签署', signed_by = ?, signed_at = datetime('now','localtime') WHERE id = ?")
117	      .run(technician_id, step.id);
118	    const tech = db.prepare('SELECT * FROM technicians WHERE id = ?').get(technician_id);
119	    addLog(card.id, tech.name, '步骤签署', `步骤${step.seq}：${step.content}`);
120	    const remaining = db.prepare(
121	      "SELECT COUNT(*) c FROM work_card_steps WHERE work_card_id = ? AND status = '待执行'"
122	    ).get(card.id).c;
123	    if (remaining === 0) {
124	      db.prepare("UPDATE work_cards SET status = '待放行' WHERE id = ?").run(card.id);
125	      addLog(card.id, '系统', '状态变更', '全部步骤签署完成，转入待放行');
126	    }
127	  });
128	  tx();
129	  res.json(getCardFull(card.id));
130	});
131	
132	// 追加步骤（待派工 / 进行中 / 缺件挂起 可追加；待放行、已放行禁止）
133	router.post('/:id/steps', (req, res) => {
134	  const { steps, operator } = req.body;
135	  if (!Array.isArray(steps) || steps.length === 0 || steps.some((s) => !s.content || !s.content.trim())) {
136	    return res.status(400).json({ error: '至少填写一个步骤内容' });
137	  }
138	  const card = db.prepare('SELECT * FROM work_cards WHERE id = ?').get(req.params.id);
139	  if (!card) return res.status(404).json({ error: '工卡不存在' });
140	  if (['待放行', '已放行', '已作废'].includes(card.status)) {
141	    return res.status(409).json({ error: `当前状态为「${card.status}」，不能再追加步骤` });
142	  }
143	
144	  const tx = db.transaction(() => {
145	    const maxSeq = db.prepare(
146	      'SELECT COALESCE(MAX(seq), 0) m FROM work_card_steps WHERE work_card_id = ?'
147	    ).get(card.id).m;
148	    const ins = db.prepare('INSERT INTO work_card_steps (work_card_id, seq, content, standard) VALUES (?, ?, ?, ?)');
