              <tr><td colSpan={8}><div className="empty">没有符合条件的工卡</div></td></tr>
            )}
          </tbody>
        </table>
      </div>

      {showNew && (
        <NewCardModal
          fleet={fleet}
          defaultAircraft={searchParams.get('aircraft') || ''}
          onClose={() => setShowNew(false)}
          onCreated={(card) => navigate(`/workcards/${card.id}`)}
        />
